function createWatchVideoSubagentConfig(options2) {
  const { includeVideoReviewReference } = options2;
  return {
    subagent_type: new SubagentType({
      type: {
        // Keep the existing proto case for wire compatibility.
        case: "watchVideo",
        value: new SubagentTypeWatchVideo()
      }
    }),
    description: [
      "Describe or analyze videos with an expert video description and analysis model.",
      ...includeVideoReviewReference ? [WATCH_VIDEO_REVIEW_ROUTING_DESCRIPTION] : [],
      "Use this subagent type to generate a description of user-provided videos, or to ask specific questions about said videos.",
      "Pass file paths via the `file_attachments` parameter.",
      'ALWAYS start by asking for a video description by asking "Describe what is happening in the attached video, in detail".',
      "You may resume the same subagent to ask more specific, detailed follow-up questions.",
      "When using, include relevant context about the video, e.g. details from the conversation about what the video may contain and why it is relevant (do not make assumptions, just share what you know).",
      "When resuming, you need not re-attach the videos."
    ].join(" "),
    preserveTaskTool: false,
    permissionMode: CustomSubagentPermissionMode.READONLY,
    defaultModelIds: ["gemini-3.1-pro", "gemini-3-flash", "gemini-2.5-flash"],
    forceDefaultModel: true,
    systemReminder: () => WATCH_VIDEO_SUBAGENT_PROMPT,
    systemPromptOverride: createMediaSubagentSystemPromptOverride(WATCH_VIDEO_SUBAGENT_PROMPT),
    // No tools - this subagent only does Q&A over the inputted media.
    toolsOverride: () => []
  };
}

